package ar.facturas.extraction.pdf;

import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;

import java.io.IOException;

/**
 * Pulls the text a PDF already contains.
 *
 * <p>A PDF generated by a billing system carries its text as text, and
 * reading it is both free and exact compared to OCR. A scanned PDF
 * carries a photograph of a page and yields nothing, which is precisely
 * what tells the two apart.
 */
public final class PdfTextReader {

    /**
     * @return the text, or empty string when there is none or the file
     *         cannot be read. Never null, and never throws: for the
     *         cascade "no text" and "unreadable" lead to the same place.
     */
    public String read(byte[] pdf) {
        if (pdf == null || pdf.length == 0) {
            return "";
        }
        try (PDDocument document = Loader.loadPDF(pdf)) {
            PDFTextStripper stripper = new PDFTextStripper();
            // Reading order as laid out on the page, so an invoice's
            // columns do not come back interleaved.
            stripper.setSortByPosition(true);
            String text = stripper.getText(document);
            return text == null ? "" : text;
        } catch (IOException | RuntimeException e) {
            return "";
        }
    }
}
